 const adj=p=>{const x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,c])=>a>=0&&a<9&&c>=1&&c<=9).map(([a,c])=>cols[a]+c);};
 const seen=new Set(),groups=[],regions=[];
 for(const p of Object.keys(b)){if(seen.has(p))continue;const v=b[p],todo=[p],stones=[],libs=new Set(),bound=new Set(); seen.add(p);
 while(todo.length){const q=todo.pop();stones.push(q);for(const n of adj(q)){if(b[n]===v&&!seen.has(n)){seen.add(n);todo.push(n);}else if(b[n]===".")libs.add(n);else if(b[n]!==v)bound.add(b[n]);}}
 const o={color:v,points:stones.sort(),liberties:[...libs].sort()}; if(v===".")regions.push({points:o.points,boundaries:[...bound].sort()});else groups.push(o);
 }
 return {board:b,groups,regions};
}`);
